-- ===== Accounts, roles, devices and notifications =====
create table if not exists public.smartphones_store_admins (email text primary key);
insert into public.smartphones_store_admins (email) values ('alkahlizero564@gmail.com') on conflict do nothing;

create table if not exists public.smartphones_store_profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  email text,
  full_name text,
  phone text,
  role text not null default 'customer' check (role in ('customer', 'admin')),
  created_at timestamptz not null default now()
);

create or replace function public.smartphones_store_is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.smartphones_store_profiles where id = auth.uid() and role = 'admin')
$$;

create or replace function public.smartphones_store_role_for(mail text) returns text
language sql stable security definer set search_path = public as $$
  select case when exists (select 1 from public.smartphones_store_admins a where lower(a.email) = lower(coalesce(mail, '')))
         then 'admin' else 'customer' end
$$;

create or replace function public.smartphones_store_handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.smartphones_store_profiles (id, email, full_name, phone, role)
  values (new.id, new.email,
          nullif(new.raw_user_meta_data->>'full_name', ''),
          nullif(new.raw_user_meta_data->>'phone', ''),
          public.smartphones_store_role_for(new.email))
  on conflict (id) do nothing;
  return new;
end $$;
drop trigger if exists smartphones_store_on_auth_user_created on auth.users;
create trigger smartphones_store_on_auth_user_created after insert on auth.users
  for each row execute function public.smartphones_store_handle_new_user();

-- Accounts that already exist (e.g. the owner) get a profile, and listed admins become admins.
insert into public.smartphones_store_profiles (id, email, role)
  select u.id, u.email, public.smartphones_store_role_for(u.email) from auth.users u
  on conflict (id) do update set role = case when excluded.role = 'admin' then 'admin' else public.smartphones_store_profiles.role end;

-- A new admin email makes an existing account admin right away.
create or replace function public.smartphones_store_admin_added() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  update public.smartphones_store_profiles set role = 'admin' where lower(email) = lower(new.email);
  return new;
end $$;
drop trigger if exists smartphones_store_admin_added on public.smartphones_store_admins;
create trigger smartphones_store_admin_added after insert on public.smartphones_store_admins
  for each row execute function public.smartphones_store_admin_added();

-- Nobody can make themselves admin; only an admin changes roles.
create or replace function public.smartphones_store_protect_role() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.role is distinct from old.role and auth.uid() is not null and not public.smartphones_store_is_admin() then
    raise exception 'only an admin can change roles';
  end if;
  return new;
end $$;
drop trigger if exists smartphones_store_protect_role on public.smartphones_store_profiles;
create trigger smartphones_store_protect_role before update on public.smartphones_store_profiles
  for each row execute function public.smartphones_store_protect_role();

alter table public.smartphones_store_profiles enable row level security;
alter table public.smartphones_store_admins enable row level security;
grant select, insert, update, delete on public.smartphones_store_profiles, public.smartphones_store_admins to authenticated;
drop policy if exists "smartphones_store profiles read" on public.smartphones_store_profiles;
create policy "smartphones_store profiles read" on public.smartphones_store_profiles for select to authenticated
  using (id = auth.uid() or public.smartphones_store_is_admin());
drop policy if exists "smartphones_store profiles update" on public.smartphones_store_profiles;
create policy "smartphones_store profiles update" on public.smartphones_store_profiles for update to authenticated
  using (id = auth.uid() or public.smartphones_store_is_admin()) with check (id = auth.uid() or public.smartphones_store_is_admin());
drop policy if exists "smartphones_store admins manage" on public.smartphones_store_admins;
create policy "smartphones_store admins manage" on public.smartphones_store_admins for all to authenticated
  using (public.smartphones_store_is_admin()) with check (public.smartphones_store_is_admin());

-- Shared helper: updated_at follows every change.
create or replace function public.smartphones_store_touch() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

create table if not exists public.smartphones_store_device_tokens (
  token text primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  app text not null check (app in ('single', 'customer', 'admin')),
  platform text not null default 'android',
  updated_at timestamptz not null default now()
);
alter table public.smartphones_store_device_tokens enable row level security;
grant select, insert, update, delete on public.smartphones_store_device_tokens to authenticated;
drop policy if exists "smartphones_store own devices" on public.smartphones_store_device_tokens;
create policy "smartphones_store own devices" on public.smartphones_store_device_tokens for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- A phone can move between accounts, so registration goes through this function.
create or replace function public.smartphones_store_register_device(device_token text, app_name text, device_platform text default 'android')
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'sign in first'; end if;
  insert into public.smartphones_store_device_tokens (token, user_id, app, platform, updated_at)
  values (device_token, auth.uid(), app_name, device_platform, now())
  on conflict (token) do update set user_id = auth.uid(), app = excluded.app,
    platform = excluded.platform, updated_at = now();
end $$;
grant execute on function public.smartphones_store_register_device(text, text, text) to authenticated;

create table if not exists public.smartphones_store_notifications (
  id bigint generated always as identity primary key,
  to_user uuid references auth.users(id) on delete cascade,
  to_role text check (to_role in ('customer', 'admin')),
  title text not null,
  body text not null default '',
  data jsonb not null default '{}',
  created_by uuid default auth.uid(),
  read_at timestamptz,
  created_at timestamptz not null default now(),
  check (to_user is not null or to_role is not null)
);
alter table public.smartphones_store_notifications enable row level security;
grant select, insert, update on public.smartphones_store_notifications to authenticated;
drop policy if exists "smartphones_store notifications read" on public.smartphones_store_notifications;
create policy "smartphones_store notifications read" on public.smartphones_store_notifications for select to authenticated
  using (to_user = auth.uid() or created_by = auth.uid()
         or (to_role = 'admin' and public.smartphones_store_is_admin()) or to_role = 'customer');
-- Customers notify the admins (or themselves); admins notify anyone.
drop policy if exists "smartphones_store notifications send" on public.smartphones_store_notifications;
create policy "smartphones_store notifications send" on public.smartphones_store_notifications for insert to authenticated
  with check (created_by = auth.uid() and (to_role = 'admin' or to_user = auth.uid() or public.smartphones_store_is_admin()));
drop policy if exists "smartphones_store notifications mark read" on public.smartphones_store_notifications;
create policy "smartphones_store notifications mark read" on public.smartphones_store_notifications for update to authenticated
  using (to_user = auth.uid() or (to_role = 'admin' and public.smartphones_store_is_admin()));

