create or replace function public.smartphones_store_orders_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.smartphones_store_is_admin() then return new; end if;
  if tg_op = 'INSERT' then
    new.customer_id := auth.uid();
    new.status := 'قيد التجهيز';
    new.payment_status := 'بانتظار الدفع';
  else
    new.customer_id := old.customer_id;
    new.status := old.status;
    new.payment_status := old.payment_status;
  end if;
  return new;
end $$;
