create or replace function public.smartphones_store_reviews_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.smartphones_store_is_admin() then return new; end if;
  if tg_op = 'INSERT' then
    new.customer_id := auth.uid();
  else
    new.customer_id := old.customer_id;
  end if;
  return new;
end $$;
drop trigger if exists smartphones_store_reviews_guard on public.smartphones_store_reviews;
create trigger smartphones_store_reviews_guard before insert or update on public.smartphones_store_reviews for each row execute function public.smartphones_store_reviews_guard();
