create or replace function public.smartphones_store_stats() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.smartphones_store_is_admin() then raise exception 'admins only'; end if;
  return jsonb_build_object('categories', (select count(*) from public.smartphones_store_categories), 'products', (select count(*) from public.smartphones_store_products), 'orders', (select count(*) from public.smartphones_store_orders), 'order_items', (select count(*) from public.smartphones_store_order_items), 'reviews', (select count(*) from public.smartphones_store_reviews), '_customers', (select count(*) from public.smartphones_store_profiles where role = 'customer'));
end $$;
grant execute on function public.smartphones_store_stats() to authenticated;

