    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'smartphones_store_order_items') then execute 'alter publication supabase_realtime add table public.smartphones_store_order_items'; end if;
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'smartphones_store_reviews') then execute 'alter publication supabase_realtime add table public.smartphones_store_reviews'; end if;
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'smartphones_store_notifications') then execute 'alter publication supabase_realtime add table public.smartphones_store_notifications'; end if;
